package android.util; public class AtomicFile { private final java.io.File path; public AtomicFile(java.io.File file){path=file;} public java.io.FileOutputStream startWrite() throws Exception{return new java.io.FileOutputStream(path);} public void finishWrite(java.io.FileOutputStream stream)throws Exception{stream.close();} public void failWrite(java.io.FileOutputStream stream)throws Exception{stream.close();} }